// stores/cart.ts
import { defineStore } from 'pinia'
import { computed, ref } from 'vue'

export interface Product {
  id: string | number
  name: string
  price: number
}

export interface CartItem extends Product {
  quantity: number
}

export const useCartStore = defineStore('cart', () => {
  // State
  const items = ref<CartItem[]>([])

  // Getters
  const total = computed<number>(() =>
    items.value.reduce((sum, item) => sum + item.price * item.quantity, 0)
  )

  const itemCount = computed<number>(() =>
    items.value.reduce((sum, item) => sum + item.quantity, 0)
  )

  // Actions
  function add(product: Product, quantity = 1): void {
    if (quantity <= 0) return
    const existing = items.value.find((i) => i.id === product.id)
    if (existing) {
      existing.quantity += quantity
    } else {
      items.value.push({ ...product, quantity })
    }
  }

  function remove(id: Product['id']): void {
    items.value = items.value.filter((i) => i.id !== id)
  }

  function clear(): void {
    items.value = []
  }

  return { items, total, itemCount, add, remove, clear }
})
```

Notes:
- `add` increments quantity if the product is already in the cart.
- `remove` removes the line item entirely.
- `total` is computed from price × quantity. For real money, consider storing prices in cents to avoid floating-point errors.
